/* Crew mode: two commanders share one screen and alternate sols. */
function crewName(i){return state.crew?state.crew.names[i%2]:'';}
function handover(){const nm=crewName(state.sol-1);Story.audio.sfx('chirp');modalCard(`<h1>Pass the controls</h1><p class="crewpass">Sol ${state.sol} belongs to <b>${esc(nm)}</b>.</p><p class="source-note">${esc(crewName(state.sol-2))}, hand the screen over. ${esc(nm)} chooses today’s jobs.</p>${v3RoleHTML()}`,()=>setTimeout(v3AlertMaybe,500),`I’m ready, ${esc(nm)} →`);}
function crewHTML(){if(!state.crew)return '';const c=state.crew;return `<h3>Crew report</h3><table class="data-table crew">${[0,1].map(i=>`<tr><td>${esc(c.names[i])}</td><td>${i===0?'Engineer':'Scientist'} · ${c.acts[i]} tasks · ${c.xp[i]} XP earned</td></tr>`).join('')}</table><p class="source-note">One outpost, one result: you succeed or fail together.</p>`;}
function infoCard(kind){const n=$('night');n.classList.add('ontop');n.style.display='flex';const close=()=>{n.style.display='none';n.classList.remove('ontop');};let body;
if(kind==='how')body=`<h1>How to play</h1><ol class="card-steps"><li><div><b>Read the forecast.</b>The strip shows five real days of space weather. Red days are storms.</div></li><li><div><b>Pick your jobs.</b>Every job costs time and supplies. You cannot do everything, so choose.</div></li><li><div><b>Get ready for storms.</b>Build the storm shield before a storm day, then spend that night in the shelter.</div></li><li><div><b>Send science home.</b>Collect samples with the scanner or the rover, then send them to Earth. The message takes minutes to arrive.</div></li><li><div><b>Build your colony.</b>Use the four build pads for solar arrays, garden beds and more. Open Colony to plan, and check Pip’s sustainability score.</div></li><li><div><b>Watch Mars weather.</b>Dust storms, dust devils and cold snaps are random game events. Plan around them.</div></li></ol><p class="source-note">Click a place to walk there, or use WASD and the arrow keys. Press E to explore.</p><button class="secondary" id="replayStory">Watch the story</button>`;
else body=`<h1>About the data</h1><table class="data-table"><tr><td>Real</td><td>Daily space weather from NASA’s DONKI, a database that records what the Sun does: flares, bursts of fast particles and giant gas clouds. An archive of 2024-01-01 to 2025-10-31 is saved inside the game (static). Live mode fetches the last five days (live).</td></tr><tr><td>Simplified</td><td>DONKI watches the Sun and Earth. The game pretends each day’s event reaches Mars the same day. Dust days and Mars weather events are random game events, not NASA data. Modules, rover sites and point values are invented game units.</td></tr><tr><td>NASA observation vs. game interpretation</td><td>NASA DONKI provides real space-weather observations. Little Mars converts them into simplified Calm, Watch and Storm gameplay levels (X-class flare or solar particle event = Storm; M-class flare or a cloud of 1,500 km/s or more = Watch; anything else = Calm). These levels are educational game classifications, not official NASA astronaut-safety warnings or measured radiation levels on Mars.</td></tr><tr><td>Curated NASA archive</td><td>Little Mars contains NASA DONKI observations from January 1, 2024, through October 31, 2025 (670 daily records, retrieved ${(window.nyTime((window.DONKI_DAILY&&window.DONKI_DAILY.fetchedAt)||'2026-11-15T12:00:00Z')||'2026-11-15')}). For gameplay balance, we selected ${window.DONKI_DAILY?window.DONKI_DAILY.windows.length:148} five-day windows from the ${window.DONKI_DAILY&&window.DONKI_DAILY.windowsPossible||666} possible ones. These windows avoid starting a mission with a Storm day or having consecutive Storm days, and have one or two Storm days. The observations are real, but the selection of dates is designed for the educational game and does not represent every possible five-day period.</td></tr><tr><td>Gameplay adjustment</td><td>Some live NASA observations may be adjusted from Storm to Watch to keep missions playable. The original NASA observation is preserved, but the displayed gameplay classification may be modified. This adjustment is made for game balance and is not a change to NASA’s original scientific data. When it happens the forecast says so.</td></tr><tr><td>Privacy</td><td>Little Mars does not upload player names, ages or gameplay progress to our servers. Player profiles and progress are stored locally in the browser on the device being used. Clearing browser data may erase saved progress. Only if you choose Live mode does the game contact NASA’s DONKI service to retrieve publicly available space-weather observations; that request does not include the player’s name, age or gameplay progress (NASA’s server can still see the device’s internet address, as any website does). The archived NASA data works without an internet connection after the game has loaded.</td></tr><tr><td>Not used</td><td>NASA OSDR, NASA’s space biology and radiation data, is future work. Curiosity’s radiation measurements inspired the shelter idea.</td></tr><tr><td>Words</td><td>A sol is one day on Mars, a little longer than a day on Earth.</td></tr><tr><td>Credits</td><td>Space weather: NASA Community Coordinated Modeling Center (CCMC) DONKI, ccmc.gsfc.nasa.gov/tools/DONKI. 3D: Three.js (MIT). Sound and story: made in the browser for this game.</td></tr></table>`;
$('debrief').innerHTML=body+`<button class="primary" id="infoBack">Back</button>`;$('infoBack').onclick=close;if($('replayStory'))$('replayStory').onclick=()=>prologue(0,true);$('infoBack').focus();}
$('howBtn').onclick=()=>infoCard('how');$('aboutBtn').onclick=()=>infoCard('data');
const COACH=[['#outlook','This is the forecast. Red days are storms. Do big outdoor jobs on calm days.'],['.hud','Your supplies. Air and Power show first. Food and Safety appear as you need them. If Air, Food or Safety reaches 0, the mission ends.'],['#guide','Not sure what to do? Pip’s button walks you to the next job.']];
function coach(i){document.querySelectorAll('.coach,.coach-ring').forEach(e=>e.remove());if(i>=COACH.length){try{localStorage.setItem('lm_coached','1');}catch(e){}return;}const t=document.querySelector(COACH[i][0]);if(!t||!t.offsetParent&&getComputedStyle(t).position!=='fixed'){coach(i+1);return;}const r=t.getBoundingClientRect(),ring=document.createElement('div');ring.className='coach-ring';Object.assign(ring.style,{left:r.left-6+'px',top:r.top-6+'px',width:r.width+12+'px',height:r.height+12+'px'});const c=document.createElement('div');c.className='coach';c.setAttribute('role','dialog');c.innerHTML=`<p>${COACH[i][1]}</p><div class="row"><small>${i+1} of ${COACH.length}</small><button>${i===COACH.length-1?'Got it':'Next'}</button></div>`;document.body.append(ring,c);c.setAttribute('aria-label','Quick tip');c.querySelector('button').onclick=()=>coach(i+1);c.querySelector('button').focus();}
