let actCount=0;

/* Landing cinematic for the from-scratch camp: five shots, then a fade into the game camera. */
const CAPS=[[.2,'SOL 0 · MARS · LITTLE MARS LANDING SITE'],[3.8,'Descent engines firing. Altitude 20 metres.'],[7.7,'Touchdown. Engines off.'],[10.2,'The habitat inflates first. Everything else starts today.'],[13.3,'Commander, your outpost is waiting.']];
const CINE_LEN=15.6,CINE_T1=7.4;
function cineLerp(a,b,k){return a+(b-a)*k;}function cineEase(k){k=Math.max(0,Math.min(1,k));return k<.5?2*k*k:1-Math.pow(-2*k+2,2)/2;}
function playIntro(done){if(cine)return;const H=M.locations.find(l=>l.id==='home');cine={t:0,done,hx:H.x,hz:H.z,puffed:false,morph:0,cap:-1,rover:false,crew:false};document.body.classList.add('cine');$('cine').style.display='block';$('cineFade').style.opacity='0';$('cineSkip').focus();stationGroups.home.visible=false;stationGroups.rover.visible=false;crew.g.visible=false;player.visible=false;pip.visible=false;lander.visible=true;cine.dustT=0;Story.audio.sfx('thruster');pcam.aspect=innerWidth/innerHeight;pcam.updateProjectionMatrix();}
function endIntro(){if(!cine)return;const c=cine;cine=null;document.body.classList.remove('cine');$('cine').style.display='none';$('cineFade').style.opacity='0';lander.position.set(LAND[0],0,LAND[1]);lander.rotation.set(0,LAND_YAW,0);flame.visible=false;plumeLight.intensity=0;stationGroups.home.visible=true;stationGroups.home.scale.setScalar(1);stationGroups.rover.visible=true;crew.g.visible=true;player.visible=true;pip.visible=true;player.position.set(-3,0,3);player.rotation.y=.4;avatar.legs[0].rotation.x=avatar.legs[1].rotation.x=0;avatar.pose();syncWorld();updateHUD();save();if(c.done)c.done();}
function updateCine(dt){const c=cine,t=c.t+=dt,hx=c.hx,hz=c.hz,lx=LAND[0],lz=LAND[1],d=Math.max(0,1-t/CINE_T1),s=t-CINE_T1;
// Powered descent: the lander arrives sideways and leaning back to brake, straightens up, then lowers itself the last metres slowly.
const y=d>0?Math.pow(d,2.1)*46+d*3:-.08*Math.exp(-s*4)*Math.cos(s*13),off=Math.pow(d,1.7)*30,tilt=.34*Math.pow(d,1.15),lpx=lx-.8*off,lpz=lz-.6*off;
lander.position.set(lpx,y,lpz);lander.rotation.set(-tilt*.6,LAND_YAW,tilt*.8);
const th=d>0?(.7+.3*smooth(.5,0,d))*(.88+Math.random()*.24):Math.max(0,1-s/.3);flame.visible=th>0;flame.scale.set(.8+th*.3,th,.8+th*.3);plumeLight.position.set(lpx,Math.max(1.2,y-1.5),lpz);plumeLight.intensity=th*180;
if(y<15&&s<.5){c.dustT+=dt;if(c.dustT>.09){c.dustT=0;const a=Math.random()*6.283,r=1+Math.random()*2.5;puff(lpx+Math.cos(a)*r,lpz+Math.sin(a)*r,3,2.5+(15-y)*.35,1.3);}}
if(s>=0&&!c.puffed){c.puffed=true;puff(lx,lz,34,5.5,1.7);Story.audio.sfx('touch');}
let pos,look,fov;
if(t<3.6){const k=cineEase(t/3.6);pos=[lx+cineLerp(19,15,k),cineLerp(20,14,k),lz+cineLerp(23,18,k)];look=[lpx,y+1.5,lpz];fov=50;}
else if(t<CINE_T1+.2){const k=(t-3.6)/(CINE_T1+.2-3.6);pos=[lx+9.5,cineLerp(4.6,1.5,k),lz+12-k*2];look=[lpx,y+2.4,lpz];fov=cineLerp(48,40,k);}
else if(t<10){const k=(t-CINE_T1-.2)/(10-CINE_T1-.2);pos=[lx+9.8-k*1.6,1.3+k*.5,lz+9-k];look=[lx,2.2,lz];fov=36;}
else if(t<12.6){const k=cineEase((t-10)/2.6);pos=[lx+3.6,1.72,lz+5.2];look=[cineLerp(hx+9,hx,k),1.7,cineLerp(hz+7,hz,k)];fov=62;}
else{const k=cineEase((t-12.6)/(CINE_LEN-12.6)),ex=Math.sin(camAngle)*38,ez=1.5+Math.cos(camAngle)*38;pos=[cineLerp(lx+3.6,ex,k),cineLerp(1.72,23.5,k),cineLerp(lz+5.2,ez,k)];look=[cineLerp(hx,0,k),cineLerp(1.7,0,k),cineLerp(hz,1.5,k)];fov=cineLerp(62,38,k);}
if(y<11&&s<.35){const amp=.07*(1-Math.max(0,y)/11);pos[0]+=(Math.random()-.5)*amp;pos[1]+=(Math.random()-.5)*amp;pos[2]+=(Math.random()-.5)*amp;}
// The inflatable habitat rises out of its cargo pack.
if(t>=10.2&&t<14.2){const k=cineEase((t-10.4)/2.2);if(k>0&&!c.morphed){c.morphed=true;puff(hx,hz,22,3.2);Story.audio.sfx('ok');}stationGroups.home.visible=k>0;stationGroups.home.scale.set(.6+.4*k,Math.max(.03,k),.6+.4*k);}
if(t>=12.4){player.visible=true;const k=Math.min(1,(t-12.4)/3);player.position.set(cineLerp(hx+2,-3,k),0,cineLerp(hz+3.4,3,k));player.rotation.y=Math.atan2(-3-(hx+2),3-(hz+3.4));const g=Math.sin(t*12)*.6;avatar.legs[0].rotation.x=g;avatar.legs[1].rotation.x=-g;avatar.arms[0].rotation.x=-g*.6;avatar.arms[1].rotation.x=g*.6;avatar.pose();}
if(t>=13.4&&!c.rover){c.rover=true;stationGroups.rover.visible=true;puff(stationGroups.rover.position.x,stationGroups.rover.position.z,10,2);}
if(t>=14&&!c.crew){c.crew=true;crew.g.visible=true;}
pcam.position.set(pos[0],pos[1],pos[2]);pcam.fov=fov;pcam.aspect=innerWidth/innerHeight;pcam.updateProjectionMatrix();pcam.lookAt(look[0],look[1],look[2]);
$('cine').classList.toggle('visor',t>=10&&t<12.6);let ci=-1;CAPS.forEach((cp,i)=>{if(t>=cp[0])ci=i;});if(ci!==c.cap){c.cap=ci;$('cineCap').textContent=ci>=0?CAPS[ci][1]:'';}
$('cineFade').style.opacity=t>CINE_LEN-.7?'1':'0';if(t>=CINE_LEN)endIntro();}
$('cineSkip').onclick=endIntro;
let profile={xp:0,age:null,badges:{},run:null,best:0};try{const p=JSON.parse(localStorage.getItem('little-mars-profile')||'null');if(p&&typeof p==='object')profile={...profile,...p,badges:p.badges||{}};}catch(e){}
function saveProfile(){try{localStorage.setItem('little-mars-profile',JSON.stringify(profile));}catch(e){}}
function runEarned(){if(!profile.run||profile.run.id!==(state.runId||0))profile.run={id:state.runId||0,earned:{},finished:false};return profile.run;}
function bandSVG(b,w=44){const id='bg'+Math.random().toString(36).slice(2,7);return `<svg class="bandsvg" viewBox="0 0 48 28" width="${w}" height="${Math.round(w*28/48)}" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" x2="1"><stop offset="0" stop-color="${b.c}"/><stop offset="1" stop-color="${b.c2}"/></linearGradient></defs><path d="M4 9a4 4 0 0 1 4-4h32a4 4 0 0 1 4 4v10a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4z" fill="url(#${id})" stroke="#17353d" stroke-opacity=".35" stroke-width="1.5"/><rect x="19" y="9" width="10" height="10" rx="3" fill="#17353d" fill-opacity=".72"/><circle cx="24" cy="14" r="2.4" fill="${b.c2}"/></svg>`;}
function renderBand(){const L=M.levelOf(profile.xp),chip=$('bandChip');if(chip){chip.innerHTML=bandSVG(L.band,34)+`<span>Lv ${L.level}</span>`;chip.title=L.name+' · '+L.band.n+' wristband';chip.setAttribute('aria-label','Commander level '+L.level+', '+L.name+', '+L.band.n+' wristband. Open mission book.');}document.documentElement.style.setProperty('--band',L.band.c);document.documentElement.style.setProperty('--band2',L.band.c2);avatar.band.material=mat(L.band.c,{emissive:L.band.c,emissiveIntensity:.35});const wb=$('welcomeBand');if(wb){if(profile.xp>0){wb.classList.remove('hidden');wb.innerHTML=bandSVG(L.band,40)+`<span>Welcome back, ${L.name}. Level ${L.level}, ${L.band.n} wristband.</span>`;}else wb.classList.add('hidden');}}
function unlockNote(n){const u=M.unlocksAt(n);return u.length?' · New: '+u.join(', '):'';}
const MISSION_ICON={icefind:'air',geology:'rock0',expansion:'pad0',researcher:'comms',labrat:'rock0',upgrader:'pad0',rescue:'rover',solarfix:'solar',commsfix:'comms',gridmaster:'solar',stormchaser:'shelter',legend:'comms',shelter:'shelter',farm:'farm',samples:'rock0',reply:'comms',builder:'pad0',power:'solar',farmer:'farm',explorer:'rover',mapper:'rover',prepared:'shelter',steady:'home',colonist:'pad0',scientist:'rock0'};
function checkMissions(){const run=runEarned(),gained=[];for(const p of M.progress(state))if(p.done&&!run.earned[p.key]){run.earned[p.key]=1;gained.push({id:p.key,name:p.name.replace(/ \(.*\)$/,''),xp:p.xp});}for(const b of M.bonus(state))if(b.done&&!run.earned[b.id]){run.earned[b.id]=1;gained.push({id:b.id,name:b.name,xp:b.xp});}gained.up=null;if(gained.length){const before=M.levelOf(profile.xp).level;for(const g of gained){profile.xp+=g.xp;profile.badges[g.id]=(profile.badges[g.id]||0)+1;}const after=M.levelOf(profile.xp);if(after.level>before)gained.up=after;state.level=after.level;saveProfile();renderBand();Story.audio.sfx(gained.up?'levelup':'badge');}return gained;}
function rewardHTML(g){if(!g||!g.length)return '';return `<div class="reward">${g.map(x=>`<div class="rw"><span class="rwi">${ICO(MISSION_ICON[x.id]||'home')}</span><span><b>Mission complete: ${x.name}</b><small>Badge earned</small></span><em>+${x.xp} XP</em></div>`).join('')}${g.up?`<div class="lvup">${bandSVG(g.up.band,52)}<span><b>Level ${g.up.level}: ${g.up.name}</b><small>${g.up.band.n} wristband unlocked</small></span></div>`:''}</div>`;}
const bonusNow=checkMissions;function newBonusHTML(){return rewardHTML(checkMissions());}
function finishRun(){const run=runEarned();if(run.finished&&run.summary)return run.summary;const before=M.levelOf(profile.xp),xp=M.missionXP(state,starsFor());profile.xp+=xp;run.finished=true;const after=M.levelOf(profile.xp);state.level=after.level;run.summary={xp,up:after.level>before.level?after:null};profile.best=Math.max(profile.best||0,M.score(state).total);saveProfile();renderBand();Story.audio.sfx(run.summary.up?'levelup':'badge');return run.summary;}
function commanderHTML(){const L=M.levelOf(profile.xp),all=[...M.progress(state).map(p=>({id:p.key,name:p.name.replace(/ \(.*\)$/,'')})),...M.bonus(state).map(b=>({id:b.id,name:b.name})),{id:'scientist',name:'Science check'}];return `<div class="cmd"><div class="cmd-top">${bandSVG(L.band,76)}<div><strong>Level ${L.level} · ${L.name}</strong><small>${L.band.n} wristband${L.next?' · '+(L.next-L.xp)+' XP to Level '+(L.level+1):' · top level'}</small></div></div><div class="xpbar" role="progressbar" aria-label="Progress to next level" aria-valuenow="${Math.round(L.into*100)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${Math.round(L.into*100)}%"></i></div><div class="badges">${all.map(b=>{const n=profile.badges[b.id]||0;return `<span class="bdg${n?' on':''}${n>=3?' gold':n>=2?' silver':''}" title="${b.name}${n?' earned '+n+(n>1?' times':' time'):' not yet earned'}">${ICO(MISSION_ICON[b.id])}<small>${b.name}</small></span>`;}).join('')}</div><p class="source-note">Badges turn silver after 2 missions and gold after 3. Your level stays with you across expeditions.</p><details class="ladder"><summary>What each level unlocks</summary><ol>${M.LEVELS.map((l,i)=>{const u=M.unlocksAt(i+1);return `<li class="${L.level>=i+1?'on':''}"><b>Level ${i+1} · ${l.n}</b><small>${i===0?'Solar array, Garden bed, Ice crater trip':u.join(', ')||'Wristband and bragging rights'}</small></li>`;}).join('')}</ol></details></div>`;}

const GLOSS={safety:{q:'What is Safety?',kid:'Safety shows how well your crew is protected from space radiation. Going outside on stormy days lowers it, and a shelter helps.',pro:'Safety is a teaching score for radiation exposure. Outdoor work lowers it, more on Watch and Storm days, and shielding cuts the cost. It is not a real dose.'},storm:{q:'What makes a Storm day?',kid:'Big bursts from the Sun, like X-class flares or particle storms, make a Storm day. They can hurt astronauts who have no cover.',pro:'Storm means an X-class flare or a solar particle event is in the NASA DONKI record for that day. Watch means an M-class flare or a CME at 1500 km/s or faster.'},power:{q:'Why is power so tight?',kid:'Every machine needs power cells, and you only get a few each morning. Choose the jobs that matter most.',pro:'Power is the main budget. Unused cells are lost overnight unless you have battery banks, so spend it before bed.'},delay:{q:'Why is Earth so slow to reply?',kid:'Radio travels very fast, but Earth is far away. Your message needs about 20 minutes to get there and the answer needs 20 more.',pro:'The game uses 20 minutes one way, so a reply takes at least 40. Real Earth to Mars light time ranges from about 3 to 22 minutes.'},dust:{q:'Why does dust matter?',kid:'Mars dust is very fine. It lands on solar panels and blocks sunlight, so they make less power.',pro:'Dust on solar panels cuts their output. Dust devils can clean panels for free, as has happened to real rovers.'}};
function pipPanel(){if(!started||state.done||cine)return;const y=M.young(state),q=getQuest(),plan=M.plan(state),dy=M.explainDay(state,y),steps=(y?plan.slice(0,3):plan).map((s,i)=>`<li><b>${i+1}</b><span><strong>${s.title}</strong><small>${y?s.why:s.cost.power+' power · '+s.cost.air+' air · '+s.cost.time+' min. '+s.why}</small></span></li>`).join('');
panelHTML('Ask Pip',`<div class="pipcard"><span class="pipface" aria-hidden="true"></span><p>${y?'Hi commander! Here is what I would do next.':'Here is my read on today.'}</p></div><div class="card"><strong>${q.title}</strong><p>${q.text}</p><button class="primary" data-go="${q.id}">${y?'Take me there →':'Go there →'}</button></div><h3>My plan for today</h3>${steps?`<ol class="pipplan">${steps}</ol>`:'<p class="source-note">Nothing urgent. Rest, or explore for bonus missions.</p>'}<h3>Why is today ${dy.word}?</h3><div class="card"><p>${dy.real||'This is a practice day.'}</p><p class="source-note">${dy.rule}</p></div><h3>Ask me about</h3><div class="chips">${Object.entries(GLOSS).map(([k,g])=>`<button class="chipbtn" data-gloss="${k}">${g.q}</button>`).join('')}</div><div id="glossOut" aria-live="polite"></div>${v3AskHTML()}<button class="secondary" id="pipRead">Read this aloud</button>`,'PIP · YOUR ASSISTANT');bindActions();v3AskBind();document.querySelectorAll('[data-gloss]').forEach(b=>b.onclick=()=>{const g=GLOSS[b.dataset.gloss];$('glossOut').innerHTML=`<div class="card"><strong>${g.q}</strong><p>${y?g.kid:g.pro}</p></div>`;});$('pipRead').onclick=()=>{narration=true;say(q.title+'. '+q.text+' '+(steps?'My plan: '+plan.slice(0,3).map((s,i)=>(i+1)+', '+s.title).join('. ')+'.':''));};}
if($('pipBtn'))$('pipBtn').onclick=()=>{if(started)pipPanel();};if($('bandChip'))$('bandChip').onclick=()=>{if(started)journal();};
addEventListener('keydown',e=>{if((e.key==='p'||e.key==='P')&&started&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){if($('panel').classList.contains('open'))closePanel();else pipPanel();}if(cine&&(e.key==='Escape'||e.key===' ')){e.preventDefault();endIntro();}});
