function buildMsg(id){const [,pid,t]=id.split(':'),mo=M.MODULES[t],pad=M.locations.find(l=>l.id===pid);return `${mo.name} built at ${pad.name}! ${mo.short}.`;}
function eventLine(){const e=M.eventOf(state);return e?`<div class="ol-event"><b>${M.EVENTS[e].name} today.</b> ${M.EVENTS[e].kid}</div>`:'';}
function eventNote(res){return res.evNow?`<div class="datanote"><b>Mars weather · ${M.EVENTS[res.evNow].name}</b><br>${M.EVENTS[res.evNow].kid} This is a random game event, not NASA data.</div>`:'';}
function roverTrips(){return `<h3 style="margin:20px 0 8px;font-size:17px">Rover expeditions</h3><p class="source-note">The rover drives to far sites on its own and counts as a sample. It uses 3 power cells, 1 air and 20 minutes, with less radiation than walking.</p>`+Object.entries(M.SITES).map(([k,S])=>state.explored[k]?`<div class="feedback">✓ ${S.name}: ${S.found}</div>`:actionHTML('explore:'+k)+`<p class="source-note">${S.text}</p>`).join('');}
function padBody(id){const pad=M.PADS[id],cur=state.modules[id];let h=`<p>${pad.note}</p>`;if(cur){const mo=M.MODULES[cur];return h+`<div class="card"><strong>${mo.name} built here.</strong><p>${mo.text}${cur==='solar'?' Tomorrow morning it makes '+M.solarOut(state,id,Math.min(state.sol+1,state.days.length))+' power before upgrades.':''}</p></div>`+v3PadUp(id);}if(!M.padOpen(state,id))return h+`<div class="feedback miss"><b>Expansion pad, not open yet.</b> It opens when ${pad.need} modules are standing. You have ${Object.keys(state.modules).length}.</div>`;
h+=`<div class="card"><strong>Empty build pad</strong><p>Each pad holds one module. Power modules start working tomorrow morning, so build early. Building outside costs a little Safety.</p></div>`;for(const t of Object.keys(M.MODULES))h+=actionHTML(`build:${id}:${t}`);return h;}
function scoreHTML(){const sc=M.score(state);return `<div class="score"><div class="score-head"><b>${sc.total}</b><span>/ 100 · Pip’s sustainability score<strong>${sc.tier}</strong></span></div><p class="pipmsg">${sc.msg}</p><div class="score-bars">${sc.parts.map(p=>`<div class="sb"><span>${p.name}</span><i><b style="width:${Math.round(p.pts/p.max*100)}%"></b></i><em>${p.pts}/${p.max}</em></div>`).join('')}</div><p class="source-note"><b>Best next step:</b> ${sc.tip}</p><details class="ol-why scorewhy"><summary>How this score works</summary><p>Ten parts add up to 100. The weights are teaching choices made by the game designers, not NASA numbers. The idea: a colony that lasts needs enough <b>supplies</b> (air, food, Safety), a <b>shelter</b>, <b>life support</b>, <b>science</b>, and a power system that is good at three different things.</p><ul>${sc.parts.map(p=>`<li><b>${p.name}</b> (${p.max}): ${p.why||p.tip}</li>`).join('')}</ul><p>Power is split on purpose. A battery bank stores power but makes none, so it cannot replace solar panels. Reliability asks what happens on the dustiest day.</p></details></div>`;}
function colonyPanel(){if(!started)return;if(state.done){const built=Object.entries(state.modules).map(([id,ty])=>`<p class="source-note"><b>${M.MODULES[ty].name}</b> · Level ${M.lv(state,id)}</p>`).join('')||'<p class="source-note">Nothing was built this mission.</p>';panelHTML('Your colony',`<p>This mission is over, so the colony is now a record. Start a new expedition to build a fresh one.</p><div class="card"><strong>What you built</strong>${built}</div>${scoreHTML()}`,'FINAL COLONY');bindActions();return;}const n=Math.min(state.sol+1,state.days.length),dusty=M.isDusty(state,n),base=dusty?5:8,carry=state.sol<state.days.length?Math.min(4*M.count(state,'battery'),state.power):0,gen=state.sol<state.days.length?M.genFor(state,n):0;
panelHTML('Your colony',`<p>Power, air and food come from what you build. Each pad holds one module, so choose what your colony needs most.</p><div class="card"><strong>Tomorrow morning: about ${state.sol<state.days.length?base+gen+carry:0} power cells</strong><p>Sunlight ${base}${dusty?' (dusty day)':''} · modules +${gen} · battery saves ${carry}.</p></div><div class="card"><strong>Each night the crew uses ${M.airNight(state)} air and ${M.foodNight(state)} food</strong><p>Air recyclers cut air use. Garden beds add 12 food to each harvest. Storage: ${M.cap(state)} air and food. Research points: ${state.rp||0}.</p></div><div class="seg" role="tablist"><button role="tab" class="on" data-tab="build">Build</button><button role="tab" data-tab="rover">Rover</button><button role="tab" data-tab="sky">Weather</button></div><div data-sec="build"><h3>Build pads</h3>${M.locations.filter(l=>l.pad).map(l=>{const t=state.modules[l.id];return `<button class="action" data-go="${l.id}"><strong>${t?M.MODULES[t].name:'Empty'} · ${l.name} →</strong><small>${t?'Level '+M.lv(state,l.id)+' · '+M.MODULES[t].short:M.padOpen(state,l.id)?'Walk there and choose what to build':'Expansion pad: opens at '+M.PADS[l.id].need+' modules'}</small></button>`;}).join('')}</div><div data-sec="rover" hidden><h3>Far sites for the rover</h3><p class="source-note">Tap a site to mark it as your next trip, then drive the rover there. Its beam of light shows the way.</p>${Object.entries(M.SITES).map(([k,S])=>{const lk=M.lockText(state,'explore:'+k),rew=Object.entries(S.gain).map(([a,b])=>'+'+b+' '+({air:'air',rad:'Safety',rp:'research points',food:'food'}[a]||a)).join(', ');return `<button class="action site${siteWay===k?' picked':''}" data-way="${k}" aria-pressed="${siteWay===k}"><strong>${state.explored[k]?'✓':siteWay===k?'◉':'○'} ${S.name}</strong><small>${state.explored[k]?'Explored. Three markers wait there for the rover instruments.':lk||(siteWay===k?'Marked. Press Go to the rover, then drive to the beam. Reward: '+rew+'.':'Tap to mark. Reward: '+rew+'.')}</small></button>`;}).join('')}<button class="secondary" data-go="rover">Go to the rover →</button><button class="secondary" id="colMap">Open the Mars map</button></div><div data-sec="sky" hidden><h3>Mars weather</h3>${state.events.map((e,i)=>e?`<p class="source-note"><b>Sol ${i+1}: ${M.EVENTS[e].name}.</b> ${M.EVENTS[e].kid}</p>`:'').join('')||'<p class="source-note">Quiet skies all week.</p>'}<p class="source-note">Mars weather events are random game events, not NASA data.</p>${scoreHTML()}</div>`,'COLONY PLAN');bindActions();document.querySelectorAll('#panel [data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('#panel [data-tab]').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-selected',x===b)});document.querySelectorAll('#panel [data-sec]').forEach(s=>s.hidden=s.dataset.sec!==b.dataset.tab);});if($('colMap'))$('colMap').onclick=()=>openConsole('map');document.querySelectorAll('#panel [data-way]').forEach(b=>b.onclick=()=>{const k=b.dataset.way;if(state.explored[k]){say(M.SITES[k].name+' is already explored. Pick another site.');return;}const lk=M.lockText(state,'explore:'+k);if(lk){say(lk);return;}siteWay=siteWay===k?null:k;beep();colonyPanel();document.querySelector('#panel [data-tab="rover"]').click();});}
$('colonyBtn').onclick=()=>{if(started)colonyPanel();};
let ageSel=profile.age||null,diffTouched=false;
function setAge(a){ageSel=a;document.querySelectorAll('.agechip').forEach(c=>{const on=+c.dataset.age===a;c.classList.toggle('on',on);c.setAttribute('aria-checked',on);});const y=a<10;$('ageNote').textContent=y?'Pre-built camp, friendlier missions, and Pip guides you step by step.':'Start from scratch: your lander arrives and nothing is built yet. Cinematic landing included.';$('ageNote').classList.remove('err');if(!diffTouched&&$('diffMode'))$('diffMode').value=y?'easy':'normal';}
document.querySelectorAll('.agechip').forEach(c=>c.onclick=()=>setAge(+c.dataset.age));if($('diffMode'))$('diffMode').onchange=()=>{diffTouched=true;};if($('players'))$('players').onchange=()=>{$('crewNames').classList.toggle('hidden',$('players').value!=='2');};if(ageSel)setAge(ageSel);renderBand();
function launchExpedition(){if($('launch'))return;const n=(profile.exp||1)+1,fast=RM(),o=document.createElement('div');o.id='launch';o.setAttribute('role','status');o.setAttribute('aria-live','polite');o.innerHTML=`<div class="lx-rings" aria-hidden="true"><i></i><i></i><i></i><b>✳</b></div><div class="lx-eyebrow">New expedition</div><h2>Expedition ${n}</h2><p id="lxMsg"></p><div class="lx-bar" aria-hidden="true"><i id="lxBar"></i></div>`;document.body.appendChild(o);$('paused').style.display='none';$('night').style.display='none';keys.clear();paused=true;try{Story.audio.sfx('ok');}catch(e){}requestAnimationFrame(()=>o.classList.add('in'));const steps=['Packing the old base away…','Reading a fresh week of Sun weather…','Loading the rover onto the lander…','Touchdown on Mars!'],ms=fast?200:720;let k=0;const finish=()=>{try{newGame();prologue(0);}catch(e){paused=false;}o.classList.add('out');setTimeout(()=>o.remove(),fast?0:600);};const tick=()=>{if(k>=steps.length){finish();return;}$('lxMsg').textContent=steps[k];$('lxBar').style.width=Math.round((k+1)/steps.length*100)+'%';k++;setTimeout(tick,ms);};tick();}
function newGame(){trip=null;if(rover){rover.position.set(0,0,0);rover.rotation.y=0;}const mode=$('weekMode')?$('weekMode').value:'archive';week=v4Week(weekFor(mode));state=M.initial(Math.floor(Math.random()*99999),week.days);{const dm=$('diffMode')?$('diffMode').value:'normal',D={easy:{air:100,food:80,power:10},hard:{air:75,food:45,power:7}}[dm];if(D)Object.assign(state,D);state.difficulty=dm;}state.weekMeta={heading:week.heading,range:week.range,source:week.source,fetched:week.fetched||null,fetchedAt:week.fetchedAt||null,curated:!!week.curated,eased:week.eased||0};state.runId=Date.now();state.level=M.levelOf(profile.xp).level;state.guide=$('guideMode')?$('guideMode').value:'auto';state.crew=$('players')&&$('players').value==='2'?{names:[($('nm1').value.trim()||'Commander 1').slice(0,12),($('nm2').value.trim()||'Commander 2').slice(0,12)],acts:[0,0],xp:[0,0]}:null;{const a=ageSel||profile.age||12;state.age=a;state.camp=a>=10?'scratch':'pre';state.setup={};}v4New();profile.run={id:state.runId,earned:{},finished:false};profile.exp=(profile.exp||0)+1;profile.age=state.age;saveProfile();checkpoint=structuredClone(state);nightResult=null;started=true;paused=false;v3Reset();closePanel();route=[];routeStation=null;routeLine.visible=false;destinationRing.visible=false;$('welcome').classList.add('hidden');$('night').style.display='none';$('paused').style.display='none';player.position.set(-3,0,3);syncWorld();updateHUD();save();say(v4Welcome());}
(function liveOnChoice(){const sel=$('weekMode');if(!sel)return;const opt=sel.querySelector('option[value=live]');if(!opt)return;opt.disabled=false;opt.textContent='Live: ask NASA for the last 5 days (needs internet)';let busy=false;sel.addEventListener('change',()=>{if(sel.value!=='live'||liveWeek||busy)return;busy=true;opt.textContent='Asking NASA…';SW.live().then(w=>{liveWeek=w;opt.textContent='LIVE: the last 5 real days from NASA ('+w.range+')';}).catch(()=>{opt.textContent='Live NASA feed unavailable. The archive will be used.';sel.value='archive';}).finally(()=>{busy=false;});});})();
$('start').onclick=()=>{if(!ageSel){$('ageNote').textContent='Choose the commander’s age first. It sets the camp and the missions.';$('ageNote').classList.add('err');document.querySelector('.agechip').focus();return;}narration=$('narrate').checked;sound=true;$('sound').textContent='Sound on';Story.audio.enable(true);newGame();prologue(0);};$('resume').onclick=()=>{state=saveData.state;if(state.age!=null){ageSel=state.age;profile.age=state.age;}renderBand();checkpoint=saveData.checkpoint||structuredClone(state);started=true;narration=$('narrate').checked;$('welcome').classList.add('hidden');player.position.set(saveData.position.x,0,saveData.position.z);v3Reset();syncWorld();updateHUD();say('Welcome back! '+getQuest().text);setTimeout(v3AlertMaybe,900);};$('guide').onclick=()=>goTo(getQuest().id);$('journal').onclick=()=>{if(started)journal();};$('map').onclick=()=>{if(!started)return;panelHTML('Where shall we go?',`<p>Choose a place. Your astronaut will find a path and walk there.</p><div class="map-grid">${M.locations.map(l=>`<button data-go="${l.id}"><span class="mi">${ICO(l.id)}</span>${l.name}</button>`).join('')}</div>`,'BASE MAP');bindActions();};$('help').onclick=()=>{if(started)showHelp();};$('sound').onclick=()=>{sound=!sound;Story.audio.enable(sound);$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',sound);beep();};function retrySol(){trip=null;if(rover){rover.position.set(0,0,0);rover.rotation.y=0;}state=structuredClone(checkpoint||M.initial());state.done=false;state.success=false;nightResult=null;paused=false;closePanel();route=[];routeStation=null;routeLine.visible=false;destinationRing.visible=false;$('night').style.display='none';$('paused').style.display='none';player.position.set(-3,0,3);syncWorld();updateHUD();save();say('Fresh start! Your supplies are restored to the start of this sol. Try a different plan.');v3Reset();setTimeout(v3AlertMaybe,900);}
function showPause(){if(!started||state.done)return;paused=true;keys.clear();$('paused').style.display='flex';$('paused').querySelector('.pause-card').innerHTML='<div class="eyebrow">Take a breather</div><h2>Mission paused</h2><p>Your crew will wait for you.</p><button class="primary" id="unpause">Keep exploring →</button><button class="secondary" id="rewind">Retry this sol</button><button class="secondary" id="saveQuit">Save and go to title</button><button class="secondary" id="restart">Start a new mission</button>';$('saveQuit').onclick=()=>{save();location.reload();};$('unpause').onclick=()=>{paused=false;$('paused').style.display='none';};$('rewind').onclick=()=>{const c=$('paused').querySelector('.pause-card');c.innerHTML='<h2>Try a different plan?</h2><p>This restores your supplies and tasks to the start of this sol. Earlier sols stay completed.</p><button class="primary" id="yesRewind">Retry this sol</button><button class="secondary" id="noRewind">Keep my progress</button>';$('yesRewind').onclick=retrySol;$('noRewind').onclick=showPause;};$('restart').onclick=()=>{const c=$('paused').querySelector('.pause-card');c.innerHTML='<h2>Start over?</h2><p>This replaces your saved expedition with a fresh mission.</p><button class="primary" id="yesRestart">Start a new expedition</button><button class="secondary" id="noRestart">Keep my expedition</button><button class="secondary" id="restartTitle">Back to title screen</button>';$('yesRestart').onclick=launchExpedition;$('noRestart').onclick=showPause;$('restartTitle').onclick=()=>{save();location.reload();};};}
$('pause').onclick=showPause;
